// Decides which backend the app talks to.
//
// - Cloud mode: `amplify_outputs.json` exists in the project root (it is generated by
//   `npx ampx sandbox --outputs-out-dir .` or by an Amplify Hosting build). Auth uses Cognito and
//   data uses AppSync/DynamoDB.
// - Local mode: no outputs file. Auth and data are stored in this browser's localStorage so the
//   app can be run, demoed and tested without an AWS account. Nothing leaves the browser.
//
// `import.meta.glob` is used instead of a static import so the build does not fail when the
// (git-ignored) outputs file is absent.

import { Amplify } from 'aws-amplify'

const found = import.meta.glob('../../amplify_outputs.json', { eager: true, import: 'default' })
const outputs = Object.values(found)[0] as Record<string, unknown> | undefined

const forceLocal = import.meta.env.VITE_FORCE_LOCAL === 'true'

export const isCloudBackend: boolean = !forceLocal && !!outputs && Object.keys(outputs).length > 0

let configured = false

export function configureBackend(): void {
  if (configured || !isCloudBackend) return
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  Amplify.configure(outputs as any)
  configured = true
}
